from __future__ import absolute_import
import logging
import os
import re
import zipfile

from lxml import etree
from robot.api import logger

from hran_file_operations.exceptions import MissingSWBuildBranch, \
    MissingSemName

SOFTWARE_PACKAGE_NAME = "swReleaseVersionPackageName"
SOFTWARE_VERSION = 'swReleaseVersionName'


class SWPackage(object):
    """

    """

    def __init__(self):
        super(SWPackage, self).__init__()

    @staticmethod
    def get_node_attribute_value(node_name, path, path_within_zip):
        """
        Keyword for getting attribute from software package

        | **Author:** agata.maslowska@nokia.com
        | **Maintainer:** agata.maslowska@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Function returns value of the given node.
        | Parameter 'node_name' can be full node's name or one of following:
        | SOFTWARE_PACKAGE_NAME for "swReleaseVersionPackageName",
        | SOFTWARE_VERSION for 'swReleaseVersionName'.

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | node_name          | Yes    | That node's value will be returned    |
        +--------------------+--------+---------------------------------------+
        | path               | Yes    | Path to sw package zip file           |
        +--------------------+--------+---------------------------------------+
        | path_within_zip    | Yes    | Path to TargetBD file                 |
        |                    |        | within sw zip file                    |
        +--------------------+--------+---------------------------------------+

        | **Return value:**
        | Node's value if exists, else: None
        """
        zf = zipfile.ZipFile(path, 'r')
        for name in zf.namelist():
            if re.match("{}.*\.xml".format(path_within_zip), name):
                file_content = zf.read(name)
                tree = etree.fromstring(file_content)
                value = tree.get(node_name)
                return value
        raise IOError

    def get_targetbd_node_attribute_value(self, node_name, path):
        """
        Keyword for parsing TargetBD and getting value for given node name.

        | **Author:** agata.maslowska@nokia.com
        | **Maintainer:** agata.maslowska@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Function parses TargetBD file within sw package zip file
        | and returns value of given node.
        | Parameter 'node_name' can be full node's name or one of following:
        | SOFTWARE_PACKAGE_NAME for "swReleaseVersionPackageName",
        | SOFTWARE_VERSION for 'swReleaseVersionName'

        **Input Parameters:**

        +--------------------+--------+------------------------------------+
        | Input Parameters   | Man.   | Description                        |
        +====================+========+====================================+
        | node_name          | Yes    | That node's value will be returned |
        +--------------------+--------+------------------------------------+
        | path               | Yes    | Path to sw package zip file        |
        +--------------------+--------+------------------------------------+

        | **Return value:**
        | Node attribute's value if such exists in
        | TargetBD file within sw package,
        | None if there is no such package / TargetBD file / Node
        """
        targetbd_path = "bts_sw/TargetBD"

        try:
            node_value = self.get_node_attribute_value(node_name, path,
                                                       targetbd_path)
            logging.info("{} found.".format(path))

        except IOError:
            logging.error("No such file under given path: {}.".format(path))
            return None

        if not node_value:
            logging.error("No such param in TargetBD: {}.".format(node_name))
            return None
        else:
            logging.info("{} = {}".format(node_name, node_value))
            return node_value

    @staticmethod
    def get_last_modified_build_from_branch(path, branch):
        """
        Keyword for getting last modified zip file from specified branch.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | path               | Yes    | Path to the dir where SW are stored.  |
        +--------------------+--------+---------------------------------------+
        | branch             | Yes    | String: Selected branch.              |
        +--------------------+--------+---------------------------------------+

        .. warning::
           SWBT - support

        | **Return value:**
        | last_modified_zip: string: Name of SW build
        """
        branch = branch.upper()
        last_modified_zip = None
        last_modified_zip_time = 0.0
        for filename in os.listdir(path):
            if re.match(r'\A' + branch + '.*zip\Z', filename):
                if os.path.getmtime(
                        path + '/' + filename) > last_modified_zip_time:
                    last_modified_zip_time = os.path.getmtime(
                        path + '/' + filename)
                    last_modified_zip = filename
        if last_modified_zip:
            logger.info('Last modified SW from selected branch: {}'.format(
                last_modified_zip))
            return last_modified_zip
        raise MissingSWBuildBranch(
            'Cannot find SW build from selected branch.')

    def get_sem_version_from_build(self, path_to_zip, filename):
        """
        Keyword for getting build and feature build

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Keyword for getting build and feature build
        | from FlexiSiteEM file or SiteEM if FlexiSitemEM doesnt exists

        **Input Parameters:**

        +--------------------+--------+-------------------------+
        | Input Parameters   | Man.   | Description             |
        +====================+========+=========================+
        | path_to_zip        | Yes    | string: Path to SW dir. |
        +--------------------+--------+-------------------------+
        | filename           | Yes    | String: SW build name.  |
        +--------------------+--------+-------------------------+


        | **Return value:**
        | [feature_build, build, patch] <list>
        """
        try:
            with zipfile.ZipFile(path_to_zip + '/' + filename,
                                 'r') as files_in_zip:
                flex_site_em_name = self._find_flex_site_em_name(
                    files_in_zip)
                root = etree.fromstring(files_in_zip.read(flex_site_em_name))
                build = root.find(".//build").text
                additional_information = re.findall(r'[0-9]+', root.find(
                    ".//additionalInformation").text)
                feature_build = additional_information[0]
                patch = additional_information[1]
                logger.debug(
                    ('build:{} '
                     'feature_build:{} '
                     'patch:{}').format(build, feature_build, patch))
                return [feature_build, build, patch]
        except zipfile.BadZipfile:
            raise TypeError('Cannot get sem version from build.')

    def _find_flex_site_em_name(self, files_in_zip):
        try:
            flex_site_em_name = self._get_flex_site_em_name(
                files_in_zip)
        except StopIteration:
            logger.debug(
                "Cannot find FlexiSiteEM file in SW build. "
                "Try to find SiteEM")
            flex_site_em_name = next(f for f in files_in_zip.namelist() if f.startswith("BTS_SW/SiteEM_"))
        except Exception as e:
            logger.debug(e)
            raise
        return flex_site_em_name

    def _get_flex_site_em_name(self, files_in_zip):
        try:
            return sorted([f for f in files_in_zip.namelist() if re.match(r"BTS_SW/FCMD/WBTS\d{2}-FlexiSiteEM", f)], reverse=True)[0]
        except (StopIteration, IndexError):
            return next(f for f in files_in_zip.namelist() if f.startswith("BTS_SW/FlexiSiteEM_"))

    @staticmethod
    def get_branch_from_file_name(sw_build_name):
        """
        Keyword for getting branch from given sw_build_name

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------+
        | Input Parameters   | Man.   | Description   |
        +====================+========+===============+
        | sw_build_name      | Yes    |               |
        +--------------------+--------+---------------+

        .. warning::
           SWBT - support

        | **Return value:**
        | branch <string>
        """
        m = re.match(r"wbts[0-9.]+", sw_build_name, re.IGNORECASE)
        if m:
            return m.group()
        else:
            raise MissingSWBuildBranch('Cannot get branch from file name.')

    @staticmethod
    def get_sem_name_from_dir(path, feature_build, build, patch):
        """
        Keyword for getting SEM name which contains feature_build and build.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+------------------------+
        | Input Parameters   | Man.   | Description            |
        +====================+========+========================+
        | path               | Yes    | Path to SEM.           |
        +--------------------+--------+------------------------+
        | feature_build      | Yes    | Feature build version. |
        +--------------------+--------+------------------------+
        | build              | Yes    | Build version.         |
        +--------------------+--------+------------------------+
        | patch              | Yes    | Patch version.         |
        +--------------------+--------+------------------------+

        .. warning::
           SWBT - support


        | **Return value:**
        | sem_name <string>
        """
        dirlist = os.listdir(path)
        logger.info('fb{} b{} p{}'.format(feature_build, build, patch))
        pattern = r'.*' + str(feature_build) + '_' + str(build) + '_' + str(
            patch)
        sem_name = None
        for filename in dirlist:
            if re.search(pattern, filename):
                sem_name = filename
        if sem_name:
            return sem_name
        else:
            raise MissingSemName('Cannot get sem name.')

    @staticmethod
    def get_sw_from_file_directory(path):
        """
        Keyword for getting list of SW versions from FileDirectory.xml

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+-----------------------+
        | Input Parameters   | Man.   | Description           |
        +====================+========+=======================+
        | path               | Yes    | Path to FileDirectory |
        +--------------------+--------+-----------------------+

        | **Return value:**
        | [active_sw, passive_sw] <list>
        """
        try:
            tree = etree.parse(path)
            root = tree.getroot()
            active_sw = root.xpath('.//fileElement[@name="TargetBD" and'
                                   ' @activeFlag="TRUE"]')[0].attrib[
                            'version'][1:-4]
            passive_sw = root.xpath('.//fileElement[@name="TargetBD" and'
                                    ' @activeFlag="FALSE"]')[0].attrib[
                             'version'][1:-4]
            return [active_sw, passive_sw]
        except Exception as e:
            logger.error(e)

    @staticmethod
    def get_sw_from_currentbd(path):
        """
        Keyword for getting list of SW versions from CurrentBD.xml

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+-------------------+
        | Input Parameters   | Man.   | Description       |
        +====================+========+===================+
        | path               | Yes    | Path to CurrentBD |
        +--------------------+--------+-------------------+

        | **Return value:**
        | [active_sw, passive_sw] <list>
        """
        try:
            tree = etree.parse(path)
            root = tree.getroot()
            ns = {"ns": "nwi3_sw_bd/currentBD_WBTS_1.0.xsd"}
            return [
                root.xpath(
                    ('.//ns:buildElement[@name="TargetBD" '
                     'and @activeFlag="TRUE"]'),
                    namespaces=ns)[0].attrib[
                    'version'],
                root.xpath(
                    ('.//ns:buildElement[@name="TargetBD" '
                     'and @activeFlag="FALSE"]'),
                    namespaces=ns)[0].attrib[
                    'version']]
        except Exception as e:
            logger.error(e)
